		"timestamp": timestamp,
	}

	transferJSON, _ := json.Marshal(transfer)
	transferKey := fmt.Sprintf("TRANSFER_%s_%d", txID, timestamp.Seconds)

	// Record the transfer (no read-modify-write)
	return ctx.GetStub().PutState(transferKey, transferJSON)

	// Option 2: Use endorsement policy to enforce balance checks
	// Have endorsers verify balance before endorsing
	// This shifts validation to endorsement time, not commit time
}

// Alternative: Implement with proper error handling
