    if err != nil {
        return fmt.Errorf("failed to get client identity: %v", err)
    }

    // Verify client is authorized for this customer
    // Implementation depends on your identity mapping strategy
    if !isAuthorized(clientID, customerID) {
        return fmt.Errorf("unauthorized: client %s cannot access customer %s", clientID, customerID)
    }
    return nil
}

// Update CreateAccount
func (l *LoyaltyPointContract) CreateAccount(ctx contractapi.TransactionContextInterface, accountID string, customerID string, initialPoints int) error {
    // Add authorization check
    if err := l.checkAuthorization(ctx, customerID); err != nil {
        return err
    }
    // ... rest of function
}
```

