        return fmt.Errorf("accountID cannot be empty")
    }
    if customerID == "" {
        return fmt.Errorf("customerID cannot be empty")
    }
    if initialPoints < 0 {
        return fmt.Errorf("initialPoints cannot be negative")
    }

    // ... rest of function
}

func (l *LoyaltyPointContract) AddPoints(ctx contractapi.TransactionContextInterface, accountID string, pointsStr string) error {
    if accountID == "" {
        return fmt.Errorf("accountID cannot be empty")
    }

    // ... existing code ...

    addPoints, err := strconv.Atoi(pointsStr)
    if err != nil {
        return fmt.Errorf("invalid points value: %v", err)
    }
    if addPoints <= 0 {
        return fmt.Errorf("points to add must be positive, got %d", addPoints)
    }

    // ... rest of function
}

func (l *LoyaltyPointContract) RedeemPoints(ctx contractapi.TransactionContextInterface, accountID string, redeemAmount int) error {
    if accountID == "" {
        return fmt.Errorf("accountID cannot be empty")
    }
    if redeemAmount <= 0 {
        return fmt.Errorf("redeem amount must be positive, got %d", redeemAmount)
    }

    // ... rest of function
}
```

---

### 3. Potential Integer Overflow
**Severity:** Low  
**Affected Function:** `AddPoints`  
**Line:** 107

**Description:**  
When adding points (`account.Points += addPoints`), there's no check for integer overflow. While unlikely in practice for loyalty points, adding very large values could cause overflow.

**Recommended Fix:**
```go
import "math"

func (l *LoyaltyPointContract) AddPoints(ctx contractapi.TransactionContextInterface, accountID string, pointsStr string) error {
    // ... existing code ...

    addPoints, err := strconv.Atoi(pointsStr)
    if err != nil {
        return fmt.Errorf("invalid points value: %v", err)
    }

    // Check for overflow
    if account.Points > math.MaxInt - addPoints {
        return fmt.Errorf("adding points would cause overflow")
    }

    account.Points += addPoints
    // ... rest of function
}
```

---

### 4. Checksum Not Validated on Read
**Severity:** Low  
**Affected Functions:** `AddPoints`, `RedeemPoints`  
**Lines:** 97-102, 133-138

**Description:**  
The chaincode computes and stores a checksum but never validates it when reading account data. This means data corruption or tampering wouldn't be detected.

**Recommended Fix:**
```go
func (l *LoyaltyPointContract) validateChecksum(account *LoyaltyAccount) error {
    expectedChecksum := computeChecksum(account.AccountID, account.Points, account.Tier)
    if account.Checksum != expectedChecksum {
        return fmt.Errorf("checksum validation failed: expected %s, got %s", expectedChecksum, account.Checksum)
    }
    return nil
}

func (l *LoyaltyPointContract) AddPoints(ctx contractapi.TransactionContextInterface, accountID string, pointsStr string) error {
    // ... existing unmarshal code ...

    // Validate checksum after unmarshaling
    if err := l.validateChecksum(&account); err != nil {
        return err
    }

    // ... rest of function
}
```

---

## Positive Security Patterns Confirmed

✅ **Deterministic Operations:** All external library calls (`crypto/sha256`, `strconv.Atoi`, `strconv.Itoa`) are deterministic  
✅ **No Random Number Generation:** No use of `math/rand` or other non-deterministic sources  
✅ **No Time Dependencies:** No use of `time.Now()` or timestamps  
✅ **No External Network Calls:** No HTTP requests or external service dependencies  
✅ **Proper State Management:** Uses `GetState`/`PutState` correctly  
✅ **No Private Data Leakage:** No private data collections used  

---

## Conclusion

The chaincode correctly uses deterministic standard library functions and demonstrates safe patterns. The main security concerns are **missing access control** and **input validation**, which should be addressed before production deployment.

# Security Analysis Report: vuln_01_time.go

## Critical Vulnerabilities Found

### 1. Non-Deterministic Operation - time.Now() Usage

**Severity:** **CRITICAL**

**Affected Locations:**
- `CreateShipment` function (lines 37-39)
- `UpdateShipmentStatus` function (line 69)
- `RecordTemperature` function (lines 95-96)

**Description:**

The chaincode uses `time.Now()` to generate timestamps, which is a **non-deterministic operation** in Hyperledger Fabric. Each endorsing peer executes the chaincode independently at slightly different wall-clock times, producing different timestamp values. This causes:

1. **Endorsement Policy Failures**: Different peers generate different read-write sets, causing endorsement mismatches
2. **Transaction Rejection**: The ordering service will reject transactions where endorsers produce different outputs
3. **System Unavailability**: All transactions calling these functions will fail

**Specific Issues:**

- **Line 37**: `now := time.Now()` - Creates non-deterministic timestamp
- **Line 38**: `CreatedAt: now.Format(time.RFC3339)` - Different value per peer
- **Line 39**: `UpdatedAt: now.Format(time.RFC3339Nano)` - Nanosecond precision amplifies the problem
- **Line 69**: `shipment.UpdatedAt = time.Now().Format(time.RFC3339)` - Non-deterministic update
- **Line 95**: `shipment.Temperature = fmt.Sprintf("%s°C at %s", tempCelsius, time.Now().Format("15:04:05.000"))` - Embeds non-deterministic time in data
- **Line 96**: `shipment.UpdatedAt = time.Now().Format(time.RFC3339)` - Duplicate non-deterministic call

**Recommended Fix:**

Replace `time.Now()` with the deterministic transaction timestamp from the Fabric context:

```go
// CreateShipment - FIXED VERSION
func (s *SupplyChainContract) CreateShipment(ctx contractapi.TransactionContextInterface, id string, origin string, destination string) error {
	exists, err := s.ShipmentExists(ctx, id)
	if err != nil {
		return err
	}
	if exists {
		return fmt.Errorf("shipment %s already exists", id)
	}

	// Use deterministic transaction timestamp
	txTimestamp, err := ctx.GetStub().GetTxTimestamp()
	if err != nil {
		return fmt.Errorf("failed to get transaction timestamp: %v", err)
	}

	// Convert to time.Time for formatting
	txTime := time.Unix(txTimestamp.Seconds, int64(txTimestamp.Nanos))

	shipment := Shipment{
		ID:          id,
		Origin:      origin,
		Destination: destination,
		Status:      "CREATED",
		CreatedAt:   txTime.Format(time.RFC3339),
		UpdatedAt:   txTime.Format(time.RFC3339),
	}

	shipmentJSON, err := json.Marshal(shipment)
	if err != nil {
		return err
	}

	return ctx.GetStub().PutState(id, shipmentJSON)
}

// UpdateShipmentStatus - FIXED VERSION
func (s *SupplyChainContract) UpdateShipmentStatus(ctx contractapi.TransactionContextInterface, id string, newStatus string) error {
	shipmentJSON, err := ctx.GetStub().GetState(id)
	if err != nil {
		return fmt.Errorf("failed to read shipment %s: %v", id, err)
	}
	if shipmentJSON == nil {
		return fmt.Errorf("shipment %s does not exist", id)
	}

	var shipment Shipment
	err = json.Unmarshal(shipmentJSON, &shipment)
	if err != nil {
		return err
	}

	// Use deterministic transaction timestamp
	txTimestamp, err := ctx.GetStub().GetTxTimestamp()
	if err != nil {
		return fmt.Errorf("failed to get transaction timestamp: %v", err)
	}
	txTime := time.Unix(txTimestamp.Seconds, int64(txTimestamp.Nanos))

	shipment.Status = newStatus
	shipment.UpdatedAt = txTime.Format(time.RFC3339)

	updatedJSON, err := json.Marshal(shipment)
	if err != nil {
		return err
	}

	return ctx.GetStub().PutState(id, updatedJSON)
}

// RecordTemperature - FIXED VERSION
func (s *SupplyChainContract) RecordTemperature(ctx contractapi.TransactionContextInterface, id string, tempCelsius string) error {
	shipmentJSON, err := ctx.GetStub().GetState(id)
	if err != nil {
		return fmt.Errorf("failed to read shipment %s: %v", id, err)
	}
	if shipmentJSON == nil {
		return fmt.Errorf("shipment %s does not exist", id)
	}

	var shipment Shipment
	err = json.Unmarshal(shipmentJSON, &shipment)
	if err != nil {
		return err
	}

	// Use deterministic transaction timestamp
	txTimestamp, err := ctx.GetStub().GetTxTimestamp()
	if err != nil {
		return fmt.Errorf("failed to get transaction timestamp: %v", err)
	}
	txTime := time.Unix(txTimestamp.Seconds, int64(txTimestamp.Nanos))

	shipment.Temperature = fmt.Sprintf("%s°C at %s", tempCelsius, txTime.Format("15:04:05.000"))
	shipment.UpdatedAt = txTime.Format(time.RFC3339)

	updatedJSON, err := json.Marshal(shipment)
	if err != nil {
		return err
	}

	return ctx.GetStub().PutState(id, updatedJSON)
}
```

