### 3. Missing Access Control

**Severity:** High

**Affected Locations:**
- Line 28 (IssueToken): No authorization check
- Line 52 (TransferToken): No sender verification
- Line 107 (BurnToken): No owner verification

**Description:**
Any user can:
- Issue tokens to any owner without authorization
- Transfer tokens from any account (not just their own)
- Burn tokens from any account
- No verification that the transaction submitter is authorized to perform these operations

**Recommended Fix:**

```go
import (
    "github.com/hyperledger/fabric-contract-api-go/contractapi"
    "github.com/hyperledger/fabric-chaincode-go/pkg/cid"
)

func (t *TokenContract) IssueToken(ctx contractapi.TransactionContextInterface, owner string, amount float64) error {
    // Only admin/issuer can create tokens
    err := t.checkAdmin(ctx)
    if err != nil {
        return fmt.Errorf("unauthorized: %v", err)
    }
    // ... rest of function
}

func (t *TokenContract) TransferToken(ctx contractapi.TransactionContextInterface, from string, to string, amount float64) error {
    // Verify caller is the sender
    clientID, err := cid.GetID(ctx.GetStub())
    if err != nil {
        return err
    }

    if clientID != from {
        return fmt.Errorf("unauthorized: only token owner can transfer")
    }
    // ... rest of function
}

func (t *TokenContract) BurnToken(ctx contractapi.TransactionContextInterface, owner string, amount float64) error {
    // Verify caller is the owner
    clientID, err := cid.GetID(ctx.GetStub())
    if err != nil {
        return err
    }

    if clientID != owner {
        return fmt.Errorf("unauthorized: only token owner can burn")
    }
    // ... rest of function
}

func (t *TokenContract) checkAdmin(ctx contractapi.TransactionContextInterface) error {
    // Check if caller has admin attribute
    isAdmin, ok, err := cid.GetAttributeValue(ctx.GetStub(), "admin")
    if err != nil {
        return err
    }
    if !ok || isAdmin != "true" {
        return fmt.Errorf("caller is not an admin")
    }
    return nil
}
```

