    // Deterministic ordering to prevent deadlocks
    if from > to {
        from, to = to, from
        amount = -amount
    }

    // Read both accounts
    fromBytes, err := ctx.GetStub().GetState(from)
    if err != nil {
        return err
    }
    if fromBytes == nil {
        return fmt.Errorf

# Security Analysis: vuln_06_b_conditional_leak.go

## Critical Vulnerabilities Found

---

### 1. Iterator Resource Leak - Early Return Before Defer Registration

**Severity:** High

**Affected Code:** `ProcessClaimsByRange` function, lines 35-43

**Vulnerability Type:** Resource Leak / Iterator Management

**Description:**
The function opens an iterator with `GetStateByRange()` but places the `defer resultsIterator.Close()` statement AFTER a conditional early return. In Go, `defer` statements are only registered when execution reaches them. If the validation check finds zero claims, the function returns at line 43 before the defer at line 48 is ever registered, causing the iterator's gRPC stream to leak.

```go
resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
if err != nil {
    return fmt.Errorf("failed to get state by range: %v", err)
}

// Validation loop exhausts iterator
claimCount := 0
for resultsIterator.HasNext() {
    claimCount++
    resultsIterator.Next()
}
if claimCount == 0 {
    // VULNERABILITY: Returns without closing iterator
    return fmt.Errorf("no claims found in range %s to %s", startKey, endKey)
}

defer resultsIterator.Close() // Never reached if early return above
```

**Recommended Fix:**
Place the `defer` statement immediately after successfully obtaining the iterator:

```go
resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
if err != nil {
    return fmt.Errorf("failed to get state by range: %v", err)
}
defer resultsIterator.Close() // Move here - immediately after acquisition

claimCount := 0
for resultsIterator.HasNext() {
    claimCount++
    resultsIterator.Next()
}
if claimCount == 0 {
    return fmt.Errorf("no claims found in range %s to %s", startKey, endKey)
}
```

---

### 2. Iterator Resource Leak - Conditional Close Logic

**Severity:** High

**Affected Code:** `GetHighValueClaims` function, lines 66-95

**Vulnerability Type:** Resource Leak / Iterator Management

**Description:**
The iterator is only closed in the `else` branch (when threshold ≤ 0), but NOT in the normal execution path (when threshold > 0). The developer incorrectly assumed iterators auto-close after exhaustion. On the normal path, the function completes the loop and returns without closing the iterator, leaking resources. Additionally, error returns within the loop also leak the iterator.

```go
if threshold > 0 {
    for resultsIterator.HasNext() {
        queryResult, err := resultsIterator.Next()
        if err != nil {
            return nil, err // VULNERABILITY: leaked iterator
        }
        // ... processing ...
    }
    // VULNERABILITY: No Close() here - falls through to return
} else {
    resultsIterator.Close() // Only closed in this branch
    return nil, fmt.Errorf("threshold must be positive, got %d", threshold)
}

return highValue, nil // VULNERABILITY: iterator not closed
```

**Recommended Fix:**
Use `defer` immediately after acquiring the iterator:

```go
resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
if err != nil {
    return nil, fmt.Errorf("failed to query range: %v", err)
}
defer resultsIterator.Close() // Add defer here

var highValue []*Claim

if threshold <= 0 {
    return nil, fmt.Errorf("threshold must be positive, got %d", threshold)
}

for resultsIterator.HasNext() {
    queryResult, err := resultsIterator.Next()
    if err != nil {
        return nil, err // Now safe - defer will close
    }
    // ... processing ...
}

return highValue, nil
```

---

### 3. Iterator Resource Leak - Manual Close with Multiple Early Returns

**Severity:** High

**Affected Code:** `ArchiveOldClaims` function, lines 98-130

**Vulnerability Type:** Resource Leak / Iterator Management

**Description:**
The function relies on manual `Close()` at the end instead of using `defer`. Multiple early return paths exist (error during iteration at line 112, batch limit reached at line 125), all of which bypass the manual `Close()` call at line 129, leaking the iterator.

```go
resultsIterator, err := ctx.GetStub().GetStateByRange(prefix+"_0000", prefix+"_9999")
if err != nil {
    return 0, err
}
// VULNERABILITY: No defer - relying on manual Close()

archived := 0
for resultsIterator.HasNext() {
    queryResult, err := resultsIterator.Next()
    if err != nil {
        return archived, err // VULNERABILITY: leaked
    }

    // ... processing ...

    if archived >= 100 {
        return archived, nil // VULNERABILITY: leaked
    }
}

resultsIterator.Close() // Only reached if no early returns
return archived, nil
```

**Recommended Fix:**
Use `defer` immediately after acquiring the iterator:

```go
resultsIterator, err := ctx.GetStub().GetStateByRange(prefix+"_0000", prefix+"_9999")
if err != nil {
    return 0, err
}
defer resultsIterator.Close() // Add defer here

archived := 0
for resultsIterator.HasNext() {
    queryResult, err := resultsIterator.Next()
    if err != nil {
        return archived, err // Now safe
    }

    // ... processing ...

    if archived >= 100 {
        return archived, nil // Now safe
    }
}

return archived, nil
```

