# Security Analysis Report: vuln_06_iterator_leak.go

## Critical Vulnerabilities Found

### 1. Resource Leak - Iterator Not Closed

**Severity:** **Critical**

**Affected Functions:**
- `GetAssetsByRange` (lines 45-72)
- `SumAssetValues` (lines 76-98)
- `TransferAssetsByOwner` (lines 102-128)
- `DeactivateRange` (lines 132-159)

**Description:**
All functions that use state iterators (`GetStateByRange`, `GetStateByPartialCompositeKey`) fail to close the iterator after use. In Hyperledger Fabric, iterators maintain open gRPC streams and database cursors to the peer's state database. Failing to close these iterators causes:

- **Resource Exhaustion:** Accumulation of open file descriptors and database connections
- **Memory Leaks:** Unreleased memory buffers for query results
- **Peer Instability:** Eventually crashes the peer when system limits are reached
- **Performance Degradation:** Slows down all chaincode operations on the peer

This is especially critical because:
1. Multiple early return paths exist without cleanup
2. High-frequency invocations will rapidly exhaust resources
3. The peer cannot automatically reclaim these resources

**Recommended Fix:**

Add `defer resultsIterator.Close()` immediately after obtaining the iterator:

```go
// GetAssetsByRange - FIXED VERSION
func (ar *AssetRegistryContract) GetAssetsByRange(ctx contractapi.TransactionContextInterface, startKey string, endKey string) ([]*RegistryAsset, error) {
	resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
	if err != nil {
		return nil, fmt.Errorf("failed to get state by range: %v", err)
	}
	defer resultsIterator.Close() // CRITICAL FIX

	var assets []*RegistryAsset
	for resultsIterator.HasNext() {
		queryResult, err := resultsIterator.Next()
		if err != nil {
			return nil, err // Now safe - defer will close iterator
		}

		var asset RegistryAsset
		err = json.Unmarshal(queryResult.Value, &asset)
		if err != nil {
			return nil, err // Now safe - defer will close iterator
		}

		assets = append(assets, &asset)
	}

	return assets, nil
}

// SumAssetValues - FIXED VERSION
func (ar *AssetRegistryContract) SumAssetValues(ctx contractapi.TransactionContextInterface, startKey string, endKey string) (int, error) {
	resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
	if err != nil {
		return 0, fmt.Errorf("failed to query range: %v", err)
	}
	defer resultsIterator.Close() // CRITICAL FIX

	totalValue := 0
	for resultsIterator.HasNext() {
		queryResult, err := resultsIterator.Next()
		if err != nil {
			return 0, err
		}

		var asset RegistryAsset
		if err := json.Unmarshal(queryResult.Value, &asset); err != nil {
			return 0, err
		}
		if asset.IsActive {
			totalValue += asset.Value
		}
	}

	return totalValue, nil
}

// TransferAssetsByOwner - FIXED VERSION
func (ar *AssetRegistryContract) TransferAssetsByOwner(ctx contractapi.TransactionContextInterface, fromOwner string, toOwner string) error {
	resultsIterator, err := ctx.GetStub().GetStateByPartialCompositeKey("Asset", []string{fromOwner})
	if err != nil {
		return fmt.Errorf("failed to query assets by owner: %v", err)
	}
	defer resultsIterator.Close() // CRITICAL FIX

	for resultsIterator.HasNext() {
		queryResult, err := resultsIterator.Next()
		if err != nil {
			return err
		}

		var asset RegistryAsset
		if err := json.Unmarshal(queryResult.Value, &asset); err != nil {
			return err
		}
		asset.Owner = toOwner

		updatedJSON, err := json.Marshal(asset)
		if err != nil {
			return err
		}
		if err = ctx.GetStub().PutState(asset.ID, updatedJSON); err != nil {
			return err
		}
	}

	return nil
}

// DeactivateRange - FIXED VERSION
func (ar *AssetRegistryContract) DeactivateRange(ctx contractapi.TransactionContextInterface, startKey string, endKey string) (int, error) {
	resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
	if err != nil {
		return 0, err
	}
	defer resultsIterator.Close() // CRITICAL FIX

	count := 0
	for resultsIterator.HasNext() {
		queryResult, err := resultsIterator.Next()
		if err != nil {
			return count, err
		}

		var asset RegistryAsset
		if err := json.Unmarshal(queryResult.Value, &asset); err != nil {
			return count, err
		}

		if asset.IsActive {
			asset.IsActive = false
			updatedJSON, err := json.Marshal(asset)
			if err != nil {
				return count, err
			}
			if err = ctx.GetStub().PutState(asset.ID, updatedJSON); err != nil {
				return count, err
			}
			count++
		}
	}

	return count, nil
}
```

